with lines as (select id, service, host, log_ts, level, latency_ms, status_code, key, v from app_logs lateral view outer explode(context) e as key, v), flattened_attrs as (select latency_ms, status_code, shiftright(status_code, 2) as status_code_high, cast((status_code & 4) != 0 as int) as has_fault from lines), base as (select *, round(status_code, 2) as status_code_rounded from flattened_attrs where status_code_high < 2), filtered as (select latency_ms, status_code, has_fault, status_code_rounded, cast(status_code as string) as status_code_str from base where status_code_rounded > 77), valid as (select status_code, status_code_rounded, cast(status_code as string) as status_code_num from filtered where status_code between 328 and 433), filtered_app_logs as (select *, status_code_rounded - status_code as status_code_rounded_minus_status_code from valid where status_code between 264 and 379) select status_code, status_code_rounded, status_code_num, status_code_rounded_minus_status_code from filtered_app_logs order by status_code_rounded_minus_status_code
